import { randomBytes } from 'crypto'
import { promises as fs } from 'fs'
import path from 'path'

import type { NextConfigComplete } from '../../server/config-shared'
import type { Lockfile } from '../../build/lockfile'
import * as Log from '../../build/output/log'
import { getSharedTypesDir } from './shared-types-dir'

/**
 * Route types are generated into one directory shared by `next dev`,
 * `next build` and `next typegen` (see `getSharedTypesDir`).
 *
 * The generated files only depend on the discovered route files and the
 * resolved config, not on the mode, so every command writes the same output.
 * `next.config` is loaded per phase, so a config that returns different
 * routing settings per phase can produce different types; the last writer
 * wins in that case.
 *
 * Mode-specific types (`env.d.ts`, the webpack per-route type guards) are not
 * written here.
 */

/** The files the shared type generator owns in the shared types directory. */
export const SHARED_TYPE_FILES = {
  routes: 'routes.d.ts',
  validator: 'validator.ts',
  cacheLife: 'cache-life.d.ts',
  rootParams: 'root-params.d.ts',
  link: 'link.d.ts',
} as const

export const SHARED_TYPES_LOCK = 'lock'

/**
 * Directory (inside the shared types directory, so renames stay on one
 * filesystem) for the temporary files of in-flight atomic writes. Preserved by
 * `next build`'s clean, so it never deletes another process's pending write.
 */
export const SHARED_TYPES_TEMP_DIR = '.tmp'

/** Entries in the shared types directory that are preserved by `next build`'s `cleanDistDir`. */
export const SHARED_TYPES_PRESERVED_ENTRIES: ReadonlySet<string> = new Set([
  ...Object.values(SHARED_TYPE_FILES),
  SHARED_TYPES_LOCK,
  SHARED_TYPES_TEMP_DIR,
])

/**
 * The shared type files `next-env.d.ts` imports for the given config (see
 * `writeAppTypeDeclarations`).
 */
export function getImportedSharedTypeFiles(config: {
  strictRouteTypes: boolean
  typedRoutes: boolean
}): string[] {
  const files: string[] = [
    SHARED_TYPE_FILES.routes,
    SHARED_TYPE_FILES.rootParams,
  ]
  if (config.strictRouteTypes) {
    files.push(SHARED_TYPE_FILES.cacheLife, SHARED_TYPE_FILES.validator)
    if (config.typedRoutes) {
      files.push(SHARED_TYPE_FILES.link)
    }
  }
  return files
}

/**
 * Writes an empty module for each shared type file `next-env.d.ts` imports
 * that doesn't exist yet, so the imports resolve before the first generation
 * has finished. Existing files are never overwritten.
 */
export async function writeSharedTypePlaceholders({
  typesDir,
  strictRouteTypes,
  typedRoutes,
}: {
  typesDir: string
  strictRouteTypes: boolean
  typedRoutes: boolean
}): Promise<void> {
  await fs.mkdir(typesDir, { recursive: true })
  await Promise.all(
    getImportedSharedTypeFiles({ strictRouteTypes, typedRoutes }).map(
      async (file) => {
        try {
          // `wx` fails if the file exists, so a concurrently generated file is
          // never replaced by a placeholder.
          await fs.writeFile(
            path.join(typesDir, file),
            '// Generated by Next.js. Types are being generated.\nexport {}\n',
            { flag: 'wx' }
          )
        } catch (err: any) {
          if (err?.code !== 'EEXIST') throw err
        }
      }
    )
  )
}

/**
 * Atomically replaces `filePath` with `content` if it differs: the content is
 * written to a temporary file and renamed into place, so concurrent writers
 * and readers never see a partially written file.
 */
async function writeFileIfChanged(
  filePath: string,
  content: string
): Promise<void> {
  try {
    if ((await fs.readFile(filePath, 'utf8')) === content) {
      return
    }
  } catch {}

  const tempDir = path.join(path.dirname(filePath), SHARED_TYPES_TEMP_DIR)
  await fs.mkdir(tempDir, { recursive: true })
  // The suffix doesn't end in `.ts`, so tsconfig never includes temp files.
  const tempPath = path.join(
    tempDir,
    `${path.basename(filePath)}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`
  )
  await fs.writeFile(tempPath, content)
  try {
    await fs.rename(tempPath, filePath)
  } catch (err) {
    await fs.rm(tempPath, { force: true })
    throw err
  }
}

async function removeFile(filePath: string): Promise<void> {
  await fs.rm(filePath, { force: true })
}

/**
 * Generates the shared route types for the project: discovers every route
 * (ignoring `--debug-build-paths`), and writes the files in
 * `SHARED_TYPE_FILES` that changed.
 *
 * Generation holds the types lock (`{typesDir}/lock`) so concurrent commands
 * take turns. Waiting for it is expected and silent at first. If locking is
 * unavailable (`experimental.lockDistDir` disabled, WASM bindings, or a
 * filesystem without lock support) or the wait times out, generation runs
 * unlocked: every writer writes identical content atomically, so that is safe.
 *
 * Must be called after the SWC bindings are loaded.
 */
export async function generateSharedTypes({
  dir,
  config,
  appDir,
  pagesDir,
}: {
  dir: string
  config: NextConfigComplete
  appDir: string | undefined
  pagesDir: string | undefined
}): Promise<void> {
  const typesDir = getSharedTypesDir(dir, config)
  await fs.mkdir(typesDir, { recursive: true })

  let lockfile: Lockfile | undefined
  if (config.experimental.lockDistDir) {
    // Lazily required: the lockfile loads the SWC bindings module.
    const { Lockfile: LockfileImpl } =
      require('../../build/lockfile') as typeof import('../../build/lockfile')
    lockfile = await LockfileImpl.acquireWithWait(
      path.join(typesDir, SHARED_TYPES_LOCK),
      {
        waitingMessage:
          'Waiting for another Next.js process to finish generating types...',
      }
    )
  }

  try {
    await generateSharedTypesUnlocked({
      dir,
      config,
      appDir,
      pagesDir,
      typesDir,
    })
  } finally {
    await lockfile?.unlock().catch(() => {
      // The operating system releases the lock when the process exits.
    })
  }
}

async function generateSharedTypesUnlocked({
  dir,
  config,
  appDir,
  pagesDir,
  typesDir,
}: {
  dir: string
  config: NextConfigComplete
  appDir: string | undefined
  pagesDir: string | undefined
  typesDir: string
}): Promise<void> {
  const { discoverRoutes } =
    require('../../build/route-discovery') as typeof import('../../build/route-discovery')
  const { createRouteTypesManifest } =
    require('../../server/lib/router-utils/route-types-utils') as typeof import('../../server/lib/router-utils/route-types-utils')
  const {
    generateRouteTypesFile,
    generateRouteTypesFileStrict,
    generateLinkTypesFile,
    generateValidatorFile,
    generateValidatorFileStrict,
  } =
    require('../../server/lib/router-utils/typegen') as typeof import('../../server/lib/router-utils/typegen')
  const { generateCacheLifeTypes } =
    require('../../server/lib/router-utils/cache-life-type-utils') as typeof import('../../server/lib/router-utils/cache-life-type-utils')
  const { generateRootParamsFileContent } =
    require('../../server/lib/router-utils/root-params-type-utils') as typeof import('../../server/lib/router-utils/root-params-type-utils')

  const strictRouteTypes = Boolean(config.experimental.strictRouteTypes)
  const validatorFilePath = path.join(typesDir, SHARED_TYPE_FILES.validator)

  const isSrcDir = path
    .relative(dir, pagesDir || appDir || '')
    .startsWith('src')

  // Always discover every route, so the output doesn't depend on the command
  // (e.g. `next build --debug-build-paths` builds only some routes).
  const {
    pageRoutes,
    pageApiRoutes,
    appRoutes,
    appRouteHandlers,
    layoutRoutes,
    slots,
  } = await discoverRoutes({
    appDir,
    pagesDir,
    pageExtensions: config.pageExtensions,
    isDev: false,
    baseDir: dir,
    isSrcDir,
  })

  const manifest = await createRouteTypesManifest({
    dir,
    pageRoutes,
    appRoutes,
    appRouteHandlers,
    pageApiRoutes,
    layoutRoutes,
    slots,
    redirects: config.redirects,
    rewrites: config.rewrites,
    validatorFilePath,
  })

  const file = (name: string) => path.join(typesDir, name)

  // Wait for every write, even if one fails, so the lock isn't released while
  // writes are still in flight.
  const results = await Promise.allSettled([
    writeFileIfChanged(
      file(SHARED_TYPE_FILES.routes),
      strictRouteTypes
        ? generateRouteTypesFileStrict(manifest)
        : generateRouteTypesFile(manifest)
    ),
    config.typedRoutes === true
      ? writeFileIfChanged(
          file(SHARED_TYPE_FILES.link),
          generateLinkTypesFile(manifest)
        )
      : removeFile(file(SHARED_TYPE_FILES.link)),
    writeFileIfChanged(
      validatorFilePath,
      strictRouteTypes
        ? generateValidatorFileStrict(manifest)
        : generateValidatorFile(manifest)
    ),
    config.cacheLife && Object.keys(config.cacheLife).length > 0
      ? writeFileIfChanged(
          file(SHARED_TYPE_FILES.cacheLife),
          generateCacheLifeTypes(config.cacheLife)
        )
      : removeFile(file(SHARED_TYPE_FILES.cacheLife)),
    writeFileIfChanged(
      file(SHARED_TYPE_FILES.rootParams),
      generateRootParamsFileContent(manifest)
    ),
  ])
  for (const result of results) {
    if (result.status === 'rejected') throw result.reason
  }
}

/**
 * Runs `generate` debounced and never concurrently with itself: a `schedule()`
 * while a run is in progress causes exactly one more run once it finishes.
 * Failures are logged, as types must never crash `next dev`.
 */
export function createSharedTypesScheduler(
  generate: () => Promise<void>,
  debounceMs = 100
): { schedule(): void } {
  let timer: NodeJS.Timeout | undefined
  let running = false
  let pending = false

  const run = async () => {
    timer = undefined
    if (running) {
      pending = true
      return
    }
    running = true
    try {
      do {
        pending = false
        try {
          await generate()
        } catch (err) {
          Log.warn('Failed to generate route types:', err)
        }
      } while (pending)
    } finally {
      running = false
    }
  }

  return {
    schedule() {
      if (timer) clearTimeout(timer)
      timer = setTimeout(run, debounceMs)
      // Pending type generation must not keep the process alive.
      timer.unref?.()
    },
  }
}
